def convert_covering_seats(apps, schema_editor):
    """Covering seats (the old joint-cell override, and seats in shared cells) get the
    partner crew's basket for the same discipline as their also-covers basket."""
    CrewAssignment = apps.get_model('users', 'CrewAssignment')
    CrewGroup = apps.get_model('timesheets', 'CrewGroup')
    CrewGroupMember = apps.get_model('timesheets', 'CrewGroupMember')
    UnitDiscipline = apps.get_model('timesheets', 'UnitDiscipline')

    partner = {}
    for group in CrewGroup.objects.all():
        members = [m.crew for m in CrewGroupMember.objects.filter(group=group).select_related('crew')]
        if len(members) == 2:
            a, b = members
            partner[a.pk] = b
            partner[b.pk] = a

    def partner_basket(basket):
        if basket.crew_id is None or basket.crew_id not in partner:
            return None
        return UnitDiscipline.objects.filter(crew=partner[basket.crew_id], discipline_id=basket.discipline_id).first()

    try:
        GridCell = apps.get_model('timesheets', 'GridCell')
    except LookupError:
        # Already dropped (a fresh database runs the drop first): there are no shared cells to convert.
        GridCell = None
    for cell in (GridCell.objects.filter(shared_with_pair=True).select_related('basket') if GridCell else []):
        target = partner_basket(cell.basket)
        if target:
            CrewAssignment.objects.filter(
                basket=cell.basket, positionid_id=cell.position_id, covers_pair_override__isnull=True,
            ).update(also_covers_basket=target)

    for seat in CrewAssignment.objects.filter(covers_pair_override=True).select_related('basket'):
        target = partner_basket(seat.basket)
        if target:
            seat.also_covers_basket = target
            seat.save(update_fields=['also_covers_basket'])


